    /// Only the items in view are laid out, so a long history costs no more
    /// to draw than a short one.
    scroll: ListState,
    /// How many items, and which open, the list was last laid out with.
    laid_out: Cell<(usize, Option<usize>)>,
    /// Counts the times it was expanded.
    opened: usize,
    /// Its tables collapse the steps leading up to the answer.
    collapse_steps: bool,
}

impl HistoryList {
    fn toggle(&mut self) {
        self.expanded = !self.expanded;
        if self.expanded {
            self.opened += 1;
            // The latest are the likeliest to be looked for.
            self.scroll.scroll_to_end();
        }
    }

    /// The row: "No …", "1 …", or "N …", which does nothing while `enabled`
    /// is false, and expands the list when clicked.
    fn render_row(
        &self,
        count: usize,
        enabled: bool,
        select: fn(&mut PromptMode) -> &mut HistoryList,
        cx: &mut Context<PromptMode>,
    ) -> AnyElement {
        let theme = cx.theme();
        let label = if self.expanded {
            self.back.to_string()
        } else {
            match count {
                0 => format!("No {}", self.plural),
                1 => format!("1 {}", self.singular),
                n => format!("{n} {}", self.plural),
            }
        };
        h_flex()
            .flex_none()
            .px_2()
            .py_0p5()
            .bg(theme.tab_bar)
            .border_b_1()
            .border_color(theme.border)
            .child(
                Button::new(self.toggle)
                    .ghost()
                    .xsmall()
                    .icon(if self.expanded {
                        IconName::ChevronDown
                    } else {
                        IconName::ChevronRight
                    })
                    .label(label)
                    .disabled(!enabled)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        select(this).toggle();
                        cx.notify();
                    })),
            )
            .into_any_element()
    }

    /// Every item, oldest first, as an accordion that scrolls: each headed by
    /// its status and prompt, and the one open showing its prompt and output.
    fn render_list(
        &self,
        tasks_of: fn(&PromptMode) -> &Vec<PromptTask>,
        count: usize,
        select: fn(&mut PromptMode) -> &mut HistoryList,
        open_file: &OpenFile,
        cx: &mut Context<PromptMode>,
    ) -> AnyElement {
